package io.github.diodeme.ji.resource.local;

import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.ProjectTrustStore;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;

/** Restart-safe trust store with a versioned line format and atomic replacement. */
public final class AtomicProjectTrustStore implements ProjectTrustStore {
    private static final String HEADER = "ji-project-trust-v1";
    private final Path file;
    private final Map<ProjectIdentity, TrustDecision> decisions = new LinkedHashMap<>();

    public AtomicProjectTrustStore(Path file) {
        this.file = file.toAbsolutePath().normalize();
        load();
    }

    @Override
    public synchronized Optional<TrustDecision> find(ProjectIdentity project) {
        return Optional.ofNullable(decisions.get(project));
    }

    @Override
    public synchronized TrustDecision decide(TrustCommand command) {
        TrustDecision current = decisions.get(command.project());
        long revision = current == null ? 0 : current.revision();
        if (command.expectedRevision() != revision) {
            throw new JiException(new JiError(ErrorCode.RESOURCE_TRUST_REVISION_CONFLICT,
                    Map.of("projectId", command.project().value(),
                            "expectedRevision", Long.toString(command.expectedRevision()),
                            "currentRevision", Long.toString(revision)), Optional.empty(), Optional.empty(),
                    OptionalLong.of(revision)));
        }
        var next = new TrustDecision(command.project(), command.fingerprint(), command.decision(),
                revision + 1, command.decidedAt());
        decisions.put(command.project(), next);
        persist();
        return next;
    }

    private void load() {
        if (!Files.exists(file)) return;
        try {
            var lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            if (lines.isEmpty() || !HEADER.equals(lines.getFirst())) throw new IOException("invalid header");
            for (String line : lines.subList(1, lines.size())) {
                if (line.isBlank()) continue;
                String[] fields = line.split("\\t", -1);
                if (fields.length != 7) throw new IOException("invalid record");
                var project = new ProjectIdentity(decode(fields[0]), decode(fields[1]));
                decisions.put(project, new TrustDecision(project, new ProjectFingerprint(fields[2]),
                        Decision.valueOf(fields[3]), Long.parseLong(fields[4]), Instant.ofEpochMilli(Long.parseLong(fields[5]))));
                if (!fields[6].equals("-")) throw new IOException("reserved field");
            }
        } catch (IOException | RuntimeException failure) {
            throw new IllegalStateException("trust store is corrupt", failure);
        }
    }

    private void persist() {
        try {
            Files.createDirectories(file.getParent());
            Path temporary = Files.createTempFile(file.getParent(), file.getFileName().toString(), ".tmp");
            try {
                var lines = new java.util.ArrayList<String>();
                lines.add(HEADER);
                decisions.values().stream().sorted(java.util.Comparator.comparing(value -> value.project().value()))
                        .forEach(value -> lines.add(encode(value.project().value()) + "\t"
                                + encode(value.project().canonicalRoot()) + "\t" + value.fingerprint().value() + "\t"
                                + value.decision().name() + "\t" + value.revision() + "\t"
                                + value.decidedAt().toEpochMilli() + "\t-"));
                Files.write(temporary, lines, StandardCharsets.UTF_8);
                try {
                    Files.move(temporary, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
                } catch (java.nio.file.AtomicMoveNotSupportedException unsupported) {
                    Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING);
                }
            } finally {
                Files.deleteIfExists(temporary);
            }
        } catch (IOException failure) {
            throw new IllegalStateException("trust store write failed", failure);
        }
    }

    private static String encode(String value) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(value.getBytes(StandardCharsets.UTF_8));
    }

    private static String decode(String value) {
        return new String(Base64.getUrlDecoder().decode(value), StandardCharsets.UTF_8);
    }
}
